214→+package evolve
215→+
216→+import (
217→+	"fmt"
218→+	"time"
219→+)
220→+
221→+// Tracker manages the lifecycle of improvement suggestions.
222→+type Tracker struct {
223→+	Records map[string]*SuggestionRecord
224→+}
225→+
226→+// NewTracker creates a new Tracker with an empty record map.
227→+func NewTracker() *Tracker {
228→+	return &Tracker{Records: make(map[string]*SuggestionRecord)}
229→+}
230→+
231→+// AddSuggestion registers a new suggestion.
232→+func (t *Tracker) AddSuggestion(rec SuggestionRecord) {
233→+	t.Records[rec.ID] = &rec
234→+}
235→+
236→+// Get returns a suggestion by ID, or nil if not found.
237→+func (t *Tracker) Get(id string) *SuggestionRecord {
238→+	return t.Records[id]
239→+}
240→+
241→+// Accept marks a suggestion as accepted and records the resolution time.
242→+func (t *Tracker) Accept(id string) error {
243→+	rec, ok := t.Records[id]
244→+	if !ok {
245→+		return fmt.Errorf("suggestion %q not found", id)
246→+	}
247→+	now := time.Now()
248→+	rec.Status = "accepted"
249→+	rec.ResolvedAt = &now
250→+	return nil
251→+}
252→+
253→+// Reject marks a suggestion as rejected and records the resolution time.
254→+func (t *Tracker) Reject(id string) error {
255→+	rec, ok := t.Records[id]
256→+	if !ok {
257→+		return fmt.Errorf("suggestion %q not found", id)
258→+	}
259→+	now := time.Now()
260→+	rec.Status = "rejected"
261→+	rec.ResolvedAt = &now
262→+	return nil
263→+}
264→+
265→+// MeasureImpact sets the pre/post average scores for impact analysis.
266→+// Returns the updated record, or nil if the ID is not found.
267→+func (t *Tracker) MeasureImpact(id string, scoresBefore, scoresAfter []float64) *SuggestionRecord {
268→+	rec, ok := t.Records[id]
269→+	if !ok {
270→+		return nil
271→+	}
272→+	rec.PreAvgScore = avgOrNil(scoresBefore)
273→+	rec.PostAvgScore = avgOrNil(scoresAfter)
274→+	return rec
275→+}
276→+
277→+// Pending returns all suggestions with "pending" status.
278→+func (t *Tracker) Pending() []SuggestionRecord {
279→+	var result []SuggestionRecord
280→+	for _, rec := range t.Records {
281→+		if rec.Status == "pending" {
282→+			result = append(result, *rec)
283→+		}
284→+	}
285→+	return result
286→+}
287→+
288→+// avgOrNil computes the average of a float64 slice.
289→+// Returns nil if the slice is empty.
290→+func avgOrNil(scores []float64) *float64 {
291→+	if len(scores) == 0 {
292→+		return nil
293→+	}
294→+	var sum float64
295→+	for _, s := range scores {
