 57→// runImprove fetches session data from the SQLite cache, refreshes it if stale,
 58→// then analyzes friction patterns and optionally generates context file improvements.
 59→func runImprove(ctx context.Context, w io.Writer, last int, dryRun bool, outputJSON bool) error {
 60→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		return fmt.Errorf("not in a git repository: %w", err)
 63→	}
 64→	entireDir := filepath.Join(worktreeRoot, paths.EntireDir)
 65→
 66→	idb, err := insightsdb.Open(filepath.Join(entireDir, "insights.db"))
 67→	if err != nil {
 68→		return fmt.Errorf("open insights cache: %w", err)
 69→	}
 70→	defer func() { _ = idb.Close() }()
 71→
 72→	// Non-fatal: continue with whatever is in the cache.
 73→	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // Non-fatal; continue with stale cache
 74→
 75→	// Phase 1: Query SQLite index for recurring friction themes (2+ occurrences).
 76→	frictionThemes, err := idb.QueryRecurringFriction(ctx, 2)
 77→	if err != nil {
 78→		return fmt.Errorf("query recurring friction: %w", err)
 79→	}
 80→
 81→	// Fetch the last N sessions for summary stats.
 82→	rows, err := idb.QueryLastNSessions(ctx, last)
 83→	if err != nil {
 84→		return fmt.Errorf("query sessions: %w", err)
 85→	}
 86→
 87→	// Count total friction items across all sessions.
 88→	frictionTotal := 0
 89→	for _, r := range rows {
 90→		frictionTotal += len(r.Friction)
 91→	}
 92→
 93→	if dryRun {
 94→		if outputJSON {
 95→			return renderImproveJSONDryRun(w, frictionThemes, len(rows), frictionTotal)
 96→		}
 97→		renderImproveTerminalDryRun(w, frictionThemes, len(rows), frictionTotal)
 98→		return nil
 99→	}
100→
101→	// Phase 2: Deep-read transcripts for top friction themes.
102→	patterns := buildFrictionPatterns(frictionThemes)
103→	if err = attachTranscriptExcerpts(ctx, idb, patterns, worktreeRoot); err != nil {
104→		// Non-fatal: proceed without transcript excerpts.
105→		_ = err
106→	}
107→
108→	// Phase 3: Detect context files.
109→	contextFiles := improve.DetectContextFiles(worktreeRoot)
110→
111→	// Phase 4: Build analysis from session data + friction patterns, then generate.
112→	summaries := sessionRowsToSummaries(rows)
113→	analysis := improve.AnalyzePatterns(summaries)
114→	// Overlay the transcript excerpts we fetched into the analysis.
115→	applyExcerpts(analysis.RepeatedFriction, patterns)
116→
117→	gen := improve.Generator{Runner: &llmcli.Runner{}}
118→	suggestions, err := gen.Generate(ctx, analysis, contextFiles)
119→	if err != nil {
120→		return fmt.Errorf("generate suggestions: %w", err)
121→	}
122→
123→	report := improve.ImprovementReport{
124→		ContextFiles:  contextFiles,
125→		Suggestions:   suggestions,
126→		SessionsUsed:  len(rows),
127→		FrictionTotal: frictionTotal,
128→		PatternsFound: len(analysis.RepeatedFriction),
129→	}
130→
131→	if outputJSON {
132→		return renderImproveJSON(w, report)
133→	}
134→	renderImproveTerminal(w, report)
135→	return nil
136→}
