227→// sessionRowsToSummaries converts insightsdb rows into improve.SessionSummaryData values.
228→func sessionRowsToSummaries(rows []insightsdb.SessionRow) []improve.SessionSummaryData {
229→	summaries := make([]improve.SessionSummaryData, 0, len(rows))
230→	for _, r := range rows {
231→		s := improve.SessionSummaryData{
232→			CheckpointID: r.CheckpointID,
233→			Friction:     r.Friction,
234→		}
235→		for _, l := range r.Learnings {
236→			s.Learnings = append(s.Learnings, improve.LearningEntry{
237→				Scope:   l.Scope,
238→				Finding: l.Finding,
239→				Path:    l.Path,
240→			})
241→		}
242→		summaries = append(summaries, s)
243→	}
244→	return summaries
245→}
