282→// renderImproveTerminal writes a styled terminal view of the improvement report.
283→func renderImproveTerminal(w io.Writer, report improve.ImprovementReport) {
284→	s := termstyle.New(w)
285→
286→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Improve"))
287→	fmt.Fprintf(w, "Analyzed %d sessions | %d friction points | %d patterns found\n\n",
288→		report.SessionsUsed, report.FrictionTotal, report.PatternsFound)
289→
290→	// Context Files section.
291→	fmt.Fprintln(w, s.SectionRule("Context Files"))
292→	for _, cf := range report.ContextFiles {
293→		if cf.Exists {
294→			line := fmt.Sprintf("  %s  %d bytes", cf.Type, cf.SizeBytes)
295→			fmt.Fprintln(w, s.Render(s.Bold, line))
296→		} else {
297→			line := fmt.Sprintf("  %s  missing", cf.Type)
298→			fmt.Fprintln(w, s.Render(s.Gray, line))
299→		}
300→	}
301→	fmt.Fprintln(w)
302→
303→	// Suggestions section.
304→	fmt.Fprintln(w, s.SectionRule(fmt.Sprintf("Suggestions (%d)", len(report.Suggestions))))
305→	if len(report.Suggestions) == 0 {
306→		fmt.Fprintln(w, "  No suggestions generated.")
307→	}
308→	for i, sug := range report.Suggestions {
309→		// Title line with priority.
310→		titleLine := fmt.Sprintf("  %d. %s  %s", i+1, sug.Title, sug.Priority)
311→		fmt.Fprintln(w, s.Render(s.Bold, titleLine))
312→
313→		// Category and file.
314→		metaLine := fmt.Sprintf("     %s → %s", sug.Category, sug.FileType)
315→		fmt.Fprintln(w, s.Render(s.Dim, metaLine))
316→
317→		// Description.
318→		if sug.Description != "" {
319→			fmt.Fprintf(w, "     %s\n", sug.Description)
320→		}
321→
322→		// Diff rendering.
323→		if sug.Diff != "" {
324→			fmt.Fprintln(w)
325→			renderDiff(w, s, sug.Diff)
326→		}
327→		fmt.Fprintln(w)
328→	}
329→}
