331→// renderImproveTerminalDryRun writes a styled terminal view of the dry-run friction data.
332→func renderImproveTerminalDryRun(w io.Writer, themes []insightsdb.FrictionTheme, sessionCount, frictionTotal int) {
333→	s := termstyle.New(w)
334→
335→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Improve (dry run)"))
336→	fmt.Fprintf(w, "Analyzed %d sessions | %d friction points | %d patterns found\n\n",
337→		sessionCount, frictionTotal, len(themes))
338→
339→	fmt.Fprintln(w, s.SectionRule("Recurring Friction"))
340→	if len(themes) == 0 {
341→		fmt.Fprintln(w, "  No recurring friction patterns found.")
342→		return
343→	}
344→	for _, t := range themes {
345→		countLine := fmt.Sprintf("  [%dx] %s", t.Count, t.Text)
346→		fmt.Fprintln(w, s.Render(s.Bold, countLine))
347→		if len(t.Sessions) > 0 {
348→			fmt.Fprintln(w, s.Render(s.Gray, "       sessions: "+strings.Join(t.Sessions, ", ")))
349→		}
350→	}
351→}
352→
353→// renderDiff writes a unified diff with colored lines to w.
354→// Lines starting with '+' are rendered in green, '-' in red, '@@' in cyan,
355→// and all other lines in dim.
356→func renderDiff(w io.Writer, s termstyle.Styles, diff string) {
357→	for _, line := range strings.Split(diff, "\n") {
358→		switch {
359→		case strings.HasPrefix(line, "@@"):
360→			fmt.Fprintln(w, s.Render(s.Cyan, line))
361→		case strings.HasPrefix(line, "+"):
362→			fmt.Fprintln(w, s.Render(s.Green, line))
363→		case strings.HasPrefix(line, "-"):
364→			fmt.Fprintln(w, s.Render(s.Red, line))
365→		default:
366→			fmt.Fprintln(w, s.Render(s.Dim, line))
367→		}
368→	}
369→}
